example_solution:
package satellite

import (
	"errors"
	"slices"
)

type Node struct {
	Value string
	Left  *Node
	Right *Node
}

func TreeFromTraversals(preorder, inorder []string) (*Node, error) {
	if len(preorder) != len(inorder) {
		return nil, errors.New("traversals must have the same length")
	}
	a := slices.Clone(preorder)
	slices.Sort(a)
	b := slices.Clone(inorder)
	slices.Sort(b)
	if !slices.Equal(a, b) {
		return nil, errors.New("traversals must have the same elements")
	}
	m := make(map[string]bool)
	for _, i := range a {
		if m[i] {
			return nil, errors.New("traversals must contain unique items")
		}
		m[i] = true
	}

	if len(preorder) == 0 {
		return nil, nil
	}

	// The first element of the preorder is always the root.
	root := preorder[0]

	// The inorder can be partitioned on the root to give the left and right inorder.
	idx := slices.Index(inorder, root)
	inorderLeft, inorderRight := inorder[:idx], inorder[idx+1:]
	// With N = len(left subtree), preorder left can be found by taking the next N
	// elements after the root. The rest are preorder right.
	preorderLeft := preorder[1 : len(inorderLeft)+1]
	preorderRight := preorder[len(inorderLeft)+1:]

	left, _ := TreeFromTraversals(preorderLeft, inorderLeft)
	right, _ := TreeFromTraversals(preorderRight, inorderRight)
	return &Node{Value: root, Left: left, Right: right}, nil
}

test_code:
package satellite

import (
	"fmt"
	"strings"
	"testing"
)

func TreesEqual(a, b *Node) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	return a.Value == b.Value && TreesEqual(a.Right, b.Right) && TreesEqual(a.Left, b.Left)
}

func FmtTree(n *Node) string {
	if n == nil {
		return "{}"
	}
	return fmt.Sprintf("Node{V: %q, L: %s, R: %s}", n.Value, FmtTree(n.Left), FmtTree(n.Right))
}

func TestTreeFromTraversals(t *testing.T) {
	for _, tc := range testCases {
		t.Run(tc.description, func(t *testing.T) {
			if actual, err := TreeFromTraversals(tc.preorder, tc.inorder); tc.err == "" && err != nil {
				t.Fatalf("TreeFromTraversals(%#v, %#v) has unexpected error, %v", tc.preorder, tc.inorder, err)
			} else if tc.err != "" && err == nil {
				t.Fatalf("TreeFromTraversals(%#v, %#v) did not error; want error, %v", tc.preorder, tc.inorder, tc.err)
			} else if tc.err != "" && !strings.HasPrefix(err.Error(), tc.err) {
				t.Fatalf("TreeFromTraversals(%#v, %#v) has error %q; want error with prefix %q", tc.preorder, tc.inorder, err, tc.err)
			} else if !TreesEqual(actual, tc.expected) {
				t.Fatalf("TreeFromTraversals(%#v, %#v)\ngot: %s\nwant: %s", tc.preorder, tc.inorder, FmtTree(actual), FmtTree(tc.expected))
			}
		})
	}
}

func BenchmarkValid(b *testing.B) {
	for range b.N {
		for _, tc := range testCases {
			TreeFromTraversals(tc.preorder, tc.inorder)
		}
	}
}
